alter table public.vehicle_image_assets add column if not exists appearance_class text; alter table public.vehicle_image_assets add constraint vehicle_image_assets_appearance_class_check check (appearance_class is null or appearance_class in ('standard_or_fixed_livery','dedicated_vehicle_identity','temporary_wrapping','requires_review')); comment on column public.vehicle_image_assets.appearance_class is 'Visual nature classification independent from image content lock and realtime identity; temporary wrapping must not be mistaken for permanent stock livery.'
